@startuml

class Animal {
  +id : int
  +name : string
  +breed : string
}

class Owner {
  +id : int
  +name : string
  +address : string
  +phone : string
}

class Breed {
  +name : string
}

class Physician {
  +id : int
  +name : string
  +address : string
  +phone : string
}

class Appointment {
  +date : date
  +time : time
}

class Condition {
  +commonName : string
  +scientificName : string
}

Animal "0..1" -- "1" Owner : ownedBy
Animal "*" -- "1" Breed : isOfBreed
Physician "1" -- "*" Appointment : responsibleFor
Animal "1" -- "*" Appointment : attends
Appointment "*" -- "*" Condition : detects
Breed "*" -- "*" Condition : commonConditions

@enduml

